


%%
%[text] ## Monte-Carlo for wavelet filter

% Monte Carlo Simulation for Uncertainty in Wavelet Denoising
% This script performs a Monte Carlo simulation to estimate the uncertainty
% introduced by wavelet denoising on a noisy displacement signal.
% It assumes a known true signal (for simulation purposes), adds Gaussian noise,
% applies wavelet denoising, and computes the standard uncertainty (standard deviation)
% across multiple realizations.

% Parameters:
% - N_sim: Number of Monte Carlo simulations (e.g., 1000 for good statistics)
% - sigma: Standard deviation of the additive Gaussian noise
% - Wavelet parameters: Wavelet name (e.g., 'db4'), level of decomposition, thresholding method

% Example true signal: sinusoidal displacement d(t) = sin(t)
% Time vector: t from 0 to 10 with 1000 points

clear; clc;

% Define parameters
N = 100000;              % Number of data points
t = linspace(0, 10, N); % Time vector
true_signal = sin(t);   % True displacement signal (e.g., sin(t))

sigma = 0.1;            % Noise standard deviation
N_sim = 1000;           % Number of Monte Carlo simulations

% Preallocate matrix for denoised signals
denoised_signals = zeros(N_sim, N);

% Monte Carlo loop
for i = 1:N_sim
    % Generate noisy signal
    noisy_signal = true_signal + sigma * randn(1, N);
    
    % Apply wavelet denoising
    % wdenoise requires Wavelet Toolbox
    denoised = wdenoise(noisy_signal, 21, ...
                         'Wavelet', 'sym9', ...
                         'DenoisingMethod', 'Bayes', ...  % Stein's Unbiased Risk Estimate
                         'ThresholdRule', 'Soft', ...
                         'NoiseEstimate', 'LevelIndependent');
    
    % Store the denoised signal
    denoised_signals(i, :) = denoised;
end

% Compute statistics
% Mean denoised signal (best estimate)
mean_denoised = mean(denoised_signals, 1);

% Standard uncertainty (standard deviation across simulations)
u_c = std(denoised_signals, 1);  % Element-wise standard deviation

% Expanded uncertainty (k=2 for ~95% coverage)
U = 2 * u_c;

% If you want to compute velocity via differentiation
% Example: Finite difference for velocity v = diff(d) / dt
dt = t(2) - t(1);
velocities = zeros(N_sim, N-1);
for i = 1:N_sim
    denoised = denoised_signals(i, :);
    velocities(i, :) = diff(denoised) / dt;
end

mean_velocity = mean(velocities, 1);
u_c_velocity = std(velocities, 1);
U_velocity = 2 * u_c_velocity;

% Plot results (optional)
figure(1); %[output:66f4eb0a]
subplot(2,1,1); %[output:66f4eb0a]
plot(t, true_signal, 'k--', 'LineWidth', 1.5); hold on; %[output:66f4eb0a]
plot(t, mean_denoised, 'b', 'LineWidth', 1.5); %[output:66f4eb0a]
fill([t, fliplr(t)], [mean_denoised + U, fliplr(mean_denoised - U)], 'b', 'FaceAlpha', 0.2, 'EdgeColor', 'none'); %[output:66f4eb0a]
legend('True Signal', 'Mean Denoised', 'Uncertainty Band (k=2)'); %[output:66f4eb0a]
title('Denoised Displacement with Uncertainty'); %[output:66f4eb0a]
xlabel('Time'); %[output:66f4eb0a]
ylabel('Displacement'); %[output:66f4eb0a]

subplot(2,1,2); %[output:66f4eb0a]
plot(t(1:end-1), diff(true_signal)/dt, 'k--', 'LineWidth', 1.5); hold on; %[output:66f4eb0a]
plot(t(1:end-1), mean_velocity, 'r', 'LineWidth', 1.5); %[output:66f4eb0a]
fill([t(1:end-1), fliplr(t(1:end-1))], [mean_velocity + U_velocity, fliplr(mean_velocity - U_velocity)], 'r', 'FaceAlpha', 0.2, 'EdgeColor', 'none'); %[output:66f4eb0a]
legend('True Velocity', 'Mean Velocity', 'Uncertainty Band (k=2)'); %[output:66f4eb0a]
title('Velocity with Uncertainty'); %[output:66f4eb0a]
xlabel('Time'); %[output:66f4eb0a]
ylabel('Velocity'); %[output:66f4eb0a]

% Output summary
fprintf('Average standard uncertainty in displacement: %.4f\n', mean(u_c)); %[output:87445b06]
fprintf('Average expanded uncertainty in displacement (k=2): %.4f\n', mean(U)); %[output:29c89f49]
fprintf('Average standard uncertainty in velocity: %.4f\n', mean(u_c_velocity)); %[output:86579eeb]
fprintf('Average expanded uncertainty in velocity (k=2): %.4f\n', mean(U_velocity)); %[output:753184fb]

% Notes:
% - This assumes you have the Wavelet Toolbox in MATLAB.
% - Adjust 'level' based on your signal (e.g., use wmaxlev to find max level).
% - For real data without true_signal, use the noisy signal as input and estimate uncertainty from residuals or bootstrap methods.
% - If computing only displacement uncertainty, comment out the velocity part.
% - For non-Gaussian noise, modify the noise generation accordingly.

